//! Text attributes. Every attribute exists in two forms generated by one macro:
//! a sparse `…Attrs` (all `Option`, used by styles and local overrides) and a complete `…Props`
//! (resolved values used by the composer). Resolution layers sparse attrs over defaults.

use serde::{Deserialize, Serialize};

/// Preserve a present nullable override; a missing field still uses the sparse default.
fn deserialize_explicit_value<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    T::deserialize(deserializer).map(Some)
}

macro_rules! attr_set {
    (
        $(#[$m:meta])*
        $attrs:ident / $props:ident {
            $( $(#[$fm:meta])* $field:ident : $ty:ty = $default:expr $(=> $deserialize:literal)? ),* $(,)?
        }
    ) => {
        $(#[$m])*
        #[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
        #[serde(default, rename_all = "camelCase")]
        pub struct $attrs {
            $( $(#[$fm])* $(#[serde(deserialize_with = $deserialize)])? #[serde(skip_serializing_if = "Option::is_none")] pub $field: Option<$ty>, )*
        }

        /// Fully resolved values.
        #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
        #[serde(default, rename_all = "camelCase")]
        pub struct $props {
            $( $(#[$fm])* pub $field: $ty, )*
        }

        impl Default for $props {
            fn default() -> Self {
                Self { $( $field: $default, )* }
            }
        }

        impl $attrs {
            /// Overlay `other` on top of `self` (fields set in `other` win).
            pub fn merge(&mut self, other: &$attrs) {
                $( if other.$field.is_some() { self.$field = other.$field.clone(); } )*
            }
            pub fn is_empty(&self) -> bool {
                true $( && self.$field.is_none() )*
            }
            /// Number of fields set (for "+" override indicators).
            pub fn count(&self) -> usize {
                0 $( + self.$field.is_some() as usize )*
            }
            /// Remove local values already supplied by the applied style, keeping real differences.
            pub fn retain_differences(&mut self, base: &$props) {
                $( if self.$field.as_ref() == Some(&base.$field) { self.$field = None; } )*
            }
            /// Field names that are set (camelCase).
            pub fn keys(&self) -> Vec<&'static str> {
                let mut v = Vec::new();
                $( if self.$field.is_some() { v.push(attr_key(stringify!($field))); } )*
                v
            }
            /// Set one field from JSON by camelCase or snake_case name.
            pub fn set_json(&mut self, key: &str, value: &serde_json::Value) -> Result<(), String> {
                let k: String = key.chars().filter(|c| *c != '_').collect::<String>().to_ascii_lowercase();
                $(
                    if k == stringify!($field).replace('_', "") {
                        if value.is_null() {
                            self.$field = None;
                        } else {
                            self.$field = Some(serde_json::from_value(value.clone()).map_err(|e| format!("{key}: {e}"))?);
                        }
                        return Ok(());
                    }
                )*
                Err(unknown_attribute(key, &[ $( stringify!($field), )* ]))
            }
            /// Fields where `self` differs from `base`'s resolved value (used for "clear overrides").
            pub fn diff_from(&self, base: &$props) -> $attrs {
                let mut out = $attrs::default();
                $( if let Some(v) = &self.$field { if *v != base.$field { out.$field = Some(v.clone()); } } )*
                out
            }
            /// Names of every attribute.
            pub fn all_keys() -> &'static [&'static str] {
                &[ $( stringify!($field), )* ]
            }
        }

        impl $props {
            pub fn apply(&mut self, a: &$attrs) {
                $( if let Some(v) = &a.$field { self.$field = v.clone(); } )*
            }
            /// The attributes where `self` and `other` differ, with `other`'s values.
            pub fn delta(&self, other: &$props) -> $attrs {
                let mut out = $attrs::default();
                $( if self.$field != other.$field { out.$field = Some(other.$field.clone()); } )*
                out
            }
            /// Keep only values common to all (`None` where they differ) — for mixed selections.
            pub fn common<'a>(items: impl IntoIterator<Item = &'a $props>) -> $attrs {
                let mut it = items.into_iter();
                let Some(first) = it.next() else { return $attrs::default() };
                let mut out = $attrs { $( $field: Some(first.$field.clone()), )* };
                for p in it {
                    $( if out.$field.as_ref().is_some_and(|v| *v != p.$field) { out.$field = None; } )*
                }
                out
            }
        }
    };
}

